package com.travelplan.travel.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.*; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.Base64; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder;
@Component public class AdminTokenFilter extends OncePerRequestFilter { private final byte[] secret; public AdminTokenFilter(@Value("${security.token-secret:replace-with-at-least-32-random-characters}") String s){if(s.length()<32)throw new IllegalArgumentException("security.token-secret must contain at least 32 characters");secret=s.getBytes(StandardCharsets.UTF_8);} protected void doFilterInternal(HttpServletRequest q,HttpServletResponse r,FilterChain c)throws ServletException,IOException{if(!q.getRequestURI().startsWith("/api/")){c.doFilter(q,r);return;} String role=verify(q.getHeader("Authorization")); if(role==null){r.sendError(401,"Authentication required");return;} if(!"ADMIN".equals(role)){r.sendError(403,"Administrator role required");return;} SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken("admin",null,java.util.List.of(new SimpleGrantedAuthority("ROLE_ADMIN")))); c.doFilter(q,r);} private String verify(String h){try{if(h==null||!h.startsWith("Bearer "))return null;String[]p=h.substring(7).split("\\.",-1);Base64.Decoder d=Base64.getUrlDecoder();if(p.length!=2||!MessageDigest.isEqual(sign(p[0]),d.decode(p[1])))return null;String[]v=new String(d.decode(p[0]),StandardCharsets.UTF_8).split("\\|",-1);return v.length==6&&"travel-plan-auth".equals(v[2])&&"travel-plan-admin".equals(v[3])&&Long.parseLong(v[4])>System.currentTimeMillis()/1000?v[1]:null;}catch(RuntimeException e){return null;}} private byte[] sign(String v){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret,"HmacSHA256"));return m.doFinal(v.getBytes(StandardCharsets.UTF_8));}catch(Exception e){throw new IllegalStateException(e);}}}
